-- CNPM2 authoritative schema: auth_db
-- Run against database auth_db only. UUIDs are generated by PostgreSQL.
CREATE EXTENSION IF NOT EXISTS pgcrypto;

CREATE TABLE IF NOT EXISTS admin_users (
    admin_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    username VARCHAR(100) NOT NULL,
    password_hash VARCHAR(255) NOT NULL,
    display_name VARCHAR(150) NOT NULL,
    is_active BOOLEAN NOT NULL DEFAULT TRUE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NULL,
    last_login_at TIMESTAMPTZ NULL
);

-- Case-insensitive uniqueness as specified in the design document.
CREATE UNIQUE INDEX IF NOT EXISTS ux_admin_users_username_lower
    ON admin_users (LOWER(username));
